// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdConfigPath 是仓库根下保存各仓库阈值的配置文件。
const thresholdConfigPath = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值：
// 仓库根 config/thresholds.json 里配了该仓库就用配置值，否则回退 DefaultLowStockThreshold。
//
// 配置文件缺失、读不出来或内容不是 JSON 对象时，一律回退。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := loadThresholds()
	if !ok {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

// loadThresholds 读取仓库根的 config/thresholds.json。
// 找不到仓库根、文件不存在、读不出来或内容不是 JSON 对象时返回 ok=false。
func loadThresholds() (map[string]int, bool) {
	root, ok := repositoryRoot()
	if !ok {
		return nil, false
	}
	raw, err := os.ReadFile(filepath.Join(root, thresholdConfigPath))
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(raw, &thresholds); err != nil {
		return nil, false
	}
	if thresholds == nil {
		return nil, false
	}
	return thresholds, true
}

// repositoryRoot 从当前工作目录向上找 go.mod 定位仓库根。
// 这样进程无论从哪个子目录启动（例如 go test 以包目录为 cwd），都能读到仓库根配置。
func repositoryRoot() (string, bool) {
	dir, err := os.Getwd()
	if err != nil {
		return "", false
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// enterTempRepo 建一个只有 go.mod 的临时仓库根，把进程 cwd 切到它的子目录，
// 返回仓库根路径。子目录 cwd 用来验证 LowStockThreshold 的仓库根定位（向上找 go.mod）。
func enterTempRepo(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	if err := os.WriteFile(filepath.Join(root, "go.mod"), []byte("module example.com/tmp\n\ngo 1.25\n"), 0o644); err != nil {
		t.Fatalf("写 go.mod 失败：%v", err)
	}
	sub := filepath.Join(root, "inventory")
	if err := os.MkdirAll(sub, 0o755); err != nil {
		t.Fatalf("建子目录失败：%v", err)
	}
	previous, err := os.Getwd()
	if err != nil {
		t.Fatalf("取 cwd 失败：%v", err)
	}
	if err := os.Chdir(sub); err != nil {
		t.Fatalf("切到子目录失败：%v", err)
	}
	t.Cleanup(func() { _ = os.Chdir(previous) })
	return root
}

// writeThresholdConfig 在临时仓库根下写出 config/thresholds.json。
func writeThresholdConfig(t *testing.T, root, content string) {
	t.Helper()
	configDir := filepath.Join(root, "config")
	if err := os.MkdirAll(configDir, 0o755); err != nil {
		t.Fatalf("建 config 目录失败：%v", err)
	}
	if err := os.WriteFile(filepath.Join(configDir, "thresholds.json"), []byte(content), 0o644); err != nil {
		t.Fatalf("写配置文件失败：%v", err)
	}
}

func TestLowStockThresholdReadsConfiguredWarehouse(t *testing.T) {
	root := enterTempRepo(t)
	writeThresholdConfig(t, root, `{"xian": 9}`)

	if got := LowStockThreshold("xian"); got != 9 {
		t.Fatalf("LowStockThreshold(%q) = %d, 期望配置值 9", "xian", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置的仓库应回退默认值，得到 %d", got)
	}
}

func TestLowStockThresholdFallsBackWithoutUsableConfig(t *testing.T) {
	cases := []struct {
		name    string
		write   bool
		content string
	}{
		{"文件不存在", false, ""},
		{"空文件", true, ""},
		{"内容不是 JSON", true, "not json"},
		{"JSON 不是对象", true, `[1, 2]`},
		{"JSON 是 null", true, `null`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			root := enterTempRepo(t)
			if tc.write {
				writeThresholdConfig(t, root, tc.content)
			}
			if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
				t.Fatalf("LowStockThreshold(%q) = %d, 期望回退默认值 %d",
					"xian", got, DefaultLowStockThreshold)
			}
		})
	}
}

func TestLowStockThresholdFallsBackWhenConfigUnreadable(t *testing.T) {
	root := enterTempRepo(t)
	configDir := filepath.Join(root, "config")
	if err := os.MkdirAll(configDir, 0o755); err != nil {
		t.Fatalf("建 config 目录失败：%v", err)
	}
	// 用目录顶替配置文件，os.ReadFile 会报错，覆盖「读不出来」。
	if err := os.Mkdir(filepath.Join(configDir, "thresholds.json"), 0o755); err != nil {
		t.Fatalf("建同名目录失败：%v", err)
	}
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("读不出配置时应回退默认值，得到 %d", got)
	}
}

